solution.solution.cpp:
#include <cstdint>
#include <string>

enum class Encoding { Utf8, Utf8Bom, Utf16Le, Utf16Be, Legacy };
enum class LineEnding { Crlf, Lf, Cr };
struct Loaded { std::string text; Encoding encoding; LineEnding ending; };

namespace
{
    void putUtf8(std::string& out, std::uint32_t cp)
    {
        if (cp < 0x80) out += static_cast<char>(cp);
        else if (cp < 0x800) { out += static_cast<char>(0xC0 | (cp >> 6)); out += static_cast<char>(0x80 | (cp & 0x3F)); }
        else if (cp < 0x10000) { out += static_cast<char>(0xE0 | (cp >> 12)); out += static_cast<char>(0x80 | ((cp >> 6) & 0x3F)); out += static_cast<char>(0x80 | (cp & 0x3F)); }
        else { out += static_cast<char>(0xF0 | (cp >> 18)); out += static_cast<char>(0x80 | ((cp >> 12) & 0x3F)); out += static_cast<char>(0x80 | ((cp >> 6) & 0x3F)); out += static_cast<char>(0x80 | (cp & 0x3F)); }
    }

    // Decodes one UTF-8 sequence at i; returns the code point or -1 if invalid, and advances i.
    long nextCodePoint(const std::string& s, std::size_t& i)
    {
        const unsigned char b{ static_cast<unsigned char>(s[i]) };
        int extra; std::uint32_t cp, min;
        if (b < 0x80) { ++i; return b; }
        if ((b & 0xE0) == 0xC0) { extra = 1; cp = b & 0x1F; min = 0x80; }
        else if ((b & 0xF0) == 0xE0) { extra = 2; cp = b & 0x0F; min = 0x800; }
        else if ((b & 0xF8) == 0xF0) { extra = 3; cp = b & 0x07; min = 0x10000; }
        else return -1;
        if (i + static_cast<std::size_t>(extra) >= s.size()) return -1;
        for (int k{ 1 }; k <= extra; ++k)
        {
            const unsigned char c{ static_cast<unsigned char>(s[i + static_cast<std::size_t>(k)]) };
            if ((c & 0xC0) != 0x80) return -1;
            cp = (cp << 6) | (c & 0x3F);
        }
        if (cp < min || cp > 0x10FFFF || (cp >= 0xD800 && cp <= 0xDFFF)) return -1;
        i += static_cast<std::size_t>(extra) + 1;
        return static_cast<long>(cp);
    }

    std::string fromUtf16(const std::string& bytes, std::size_t start, bool little)
    {
        std::string out;
        auto unit = [&](std::size_t at) -> std::uint32_t {
            const auto a{ static_cast<unsigned char>(bytes[at]) }, b{ static_cast<unsigned char>(bytes[at + 1]) };
            return little ? (a | (b << 8)) : ((a << 8) | b);
        };
        for (std::size_t i{ start }; i + 1 < bytes.size(); i += 2)
        {
            const std::uint32_t u{ unit(i) };
            if (u >= 0xD800 && u <= 0xDBFF && i + 3 < bytes.size())
            {
                const std::uint32_t lo{ unit(i + 2) };
                if (lo >= 0xDC00 && lo <= 0xDFFF) { putUtf8(out, 0x10000 + ((u - 0xD800) << 10) + (lo - 0xDC00)); i += 2; continue; }
            }
            putUtf8(out, (u >= 0xD800 && u <= 0xDFFF) ? 0xFFFD : u);
        }
        return out;
    }
}

bool isValidUtf8(const std::string& bytes)
{
    std::size_t i{ 0 };
    while (i < bytes.size()) if (nextCodePoint(bytes, i) < 0) return false;
    return true;
}

Loaded decodeFile(const std::string& bytes)
{
    Loaded l{ "", Encoding::Utf8, LineEnding::Crlf };
    std::string text;
    if (bytes.rfind("\xEF\xBB\xBF", 0) == 0) { l.encoding = Encoding::Utf8Bom; text = bytes.substr(3); }
    else if (bytes.rfind("\xFF\xFE", 0) == 0) { l.encoding = Encoding::Utf16Le; text = fromUtf16(bytes, 2, true); }
    else if (bytes.rfind("\xFE\xFF", 0) == 0) { l.encoding = Encoding::Utf16Be; text = fromUtf16(bytes, 2, false); }
    else if (isValidUtf8(bytes)) text = bytes;
    else { l.encoding = Encoding::Legacy; for (unsigned char c : bytes) putUtf8(text, c); }

    int crlf{ 0 }, lf{ 0 }, cr{ 0 };
    for (std::size_t i{ 0 }; i < text.size(); ++i)
    {
        if (text[i] == '\r')
        {
            if (i + 1 < text.size() && text[i + 1] == '\n') { ++crlf; ++i; }
            else ++cr;
            l.text += '\n';
        }
        else
        {
            if (text[i] == '\n') ++lf;
            l.text += text[i];
        }
    }
    if (lf > crlf && lf >= cr) l.ending = LineEnding::Lf;
    else if (cr > crlf && cr > lf) l.ending = LineEnding::Cr;
    return l;
}

std::string encodeFile(const std::string& text, Encoding encoding, LineEnding ending)
{
    const char* eol{ ending == LineEnding::Crlf ? "\r\n" : ending == LineEnding::Lf ? "\n" : "\r" };
    std::string lines;
    for (char c : text) { if (c == '\n') lines += eol; else lines += c; }

    if (encoding == Encoding::Utf8) return lines;
    if (encoding == Encoding::Utf8Bom) return "\xEF\xBB\xBF" + lines;
    std::string out;
    std::size_t i{ 0 };
    if (encoding == Encoding::Legacy)
    {
        while (i < lines.size()) { const long cp{ nextCodePoint(lines, i) }; out += cp >= 0 && cp <= 0xFF ? static_cast<char>(cp) : '?'; if (cp < 0) ++i; }
        return out;
    }
    const bool little{ encoding == Encoding::Utf16Le };
    out = little ? "\xFF\xFE" : "\xFE\xFF";
    auto put = [&](std::uint32_t u) {
        const char lo{ static_cast<char>(u & 0xFF) }, hi{ static_cast<char>(u >> 8) };
        if (little) { out += lo; out += hi; } else { out += hi; out += lo; }
    };
    while (i < lines.size())
    {
        long cp{ nextCodePoint(lines, i) };
        if (cp < 0) { cp = 0xFFFD; ++i; }
        if (cp >= 0x10000) { const std::uint32_t v{ static_cast<std::uint32_t>(cp) - 0x10000 }; put(0xD800 + (v >> 10)); put(0xDC00 + (v & 0x3FF)); }
        else put(static_cast<std::uint32_t>(cp));
    }
    return out;
}

unitTests:
TEST("strict UTF-8") { CHECK(isValidUtf8("plain")); CHECK(isValidUtf8("\xC3\xA9t\xC3\xA9")); CHECK(!isValidUtf8("\xC0\xAF")); CHECK(!isValidUtf8("\xED\xA0\x80")); CHECK(!isValidUtf8("caf\xE9")); CHECK(!isValidUtf8("\xE2\x82")); }
TEST("encodings") {
    Loaded a = decodeFile("\xEF\xBB\xBFhi"); CHECK(a.encoding == Encoding::Utf8Bom); CHECK_EQ(a.text, std::string("hi"));
    Loaded b = decodeFile(std::string("\xFF\xFEh\0\xE9\0=\xD8\0\xDE", 10)); CHECK(b.encoding == Encoding::Utf16Le); CHECK_EQ(b.text, std::string("h\xC3\xA9\xF0\x9F\x98\x80"));
    Loaded c = decodeFile(std::string("\xFE\xFF\0h\0i", 6)); CHECK(c.encoding == Encoding::Utf16Be); CHECK_EQ(c.text, std::string("hi"));
    Loaded d = decodeFile("caf\xE9"); CHECK(d.encoding == Encoding::Legacy); CHECK_EQ(d.text, std::string("caf\xC3\xA9"));
    Loaded e = decodeFile("caf\xC3\xA9"); CHECK(e.encoding == Encoding::Utf8);
}
TEST("line endings") {
    Loaded a = decodeFile("a\r\nb\r\nc\n"); CHECK(a.ending == LineEnding::Crlf); CHECK_EQ(a.text, std::string("a\nb\nc\n"));
    CHECK(decodeFile("a\nb\nc\r\n").ending == LineEnding::Lf); CHECK(decodeFile("a\rb\rc").ending == LineEnding::Cr);
    CHECK(decodeFile("a\nb\r\n").ending == LineEnding::Crlf); CHECK(decodeFile("one line").ending == LineEnding::Crlf); CHECK(decodeFile("a\rb\n").ending == LineEnding::Lf);
}
TEST("saving it back") {
    CHECK_EQ(encodeFile("a\nb", Encoding::Utf8, LineEnding::Crlf), std::string("a\r\nb")); CHECK_EQ(encodeFile("a\nb", Encoding::Utf8Bom, LineEnding::Lf), std::string("\xEF\xBB\xBF" "a\nb"));
    CHECK_EQ(encodeFile("h\xC3\xA9\xF0\x9F\x98\x80", Encoding::Utf16Le, LineEnding::Crlf), std::string("\xFF\xFEh\0\xE9\0=\xD8\0\xDE", 10));
    CHECK_EQ(encodeFile("caf\xC3\xA9 \xE2\x82\xAC", Encoding::Legacy, LineEnding::Lf), std::string("caf\xE9 ?"));
    for (const std::string file : { std::string("x\r\ny\r\n"), std::string("\xEF\xBB\xBFz\n"), std::string("\xFE\xFF\0a\0\r\0\n", 8) }) {
        const Loaded l = decodeFile(file); CHECK_EQ(encodeFile(l.text, l.encoding, l.ending), file);
    }
}

